import React, { type PropsWithChildren } from 'react';

import { DEFAULT_CHART_HEIGHT } from './constants/defaults.js';
import { XYChartAxesConfigContext } from './context/axes/XYChartAxesConfig.context.js';
import { useXYChartConfig } from './hooks/useXYChartConfig.js';
import { XYChartChartDataProvider } from './providers/XYChartDataProvider.js';
import { HeatmapSeries } from './slots/HeatmapSeries.js';
import { XAxis } from './slots/XAxis.js';
import type { XYChartProps } from './types/xy-chart.js';
import { XYChart as _XYChart } from './XYChart.js';
import { coerceSizeValue } from '../core/functions/coerceSizeValue.js';

/**
 * @internal
 */
export const XYChartRoot = (props: PropsWithChildren<XYChartProps>) => {
  const { data, children, height } = props;

  const chartConfig = useXYChartConfig(children);
  const { heatmapSeries, axes } = chartConfig;
  const chartHeight = coerceSizeValue(height ?? DEFAULT_CHART_HEIGHT);

  return (
    <XYChartAxesConfigContext.Provider value={axes}>
      <XYChartChartDataProvider
        data={data}
        seriesVariantsProps={[heatmapSeries]}
      >
        <_XYChart height={chartHeight} />
      </XYChartChartDataProvider>
    </XYChartAxesConfigContext.Provider>
  );
};

/**
 * @internal
 * An XY chart is a type of graphical representation used to display the relationship between two variables.
 * It consists of points plotted on a Cartesian coordinate system, where each point represents a single observation
 * with its x and y coordinates.
 */
export const XYChart = Object.assign(XYChartRoot, {
  HeatmapSeries,
  XAxis,
});

XYChart['displayName'] = 'XYChart';
